76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
80	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
81	     * logger named {@code AUDIT}.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
87	     * at least one dot and no whitespace on either side.
88	     */
89	    private static final Pattern EMAIL_PATTERN =
90	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
91	
92	    /**
93	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
94	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
95	     * response naming {@code email}.
96	     */
97	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
98	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
99	
100	    /**
101	     * Common street-type abbreviations expanded during address normalization. Keys are the
102	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
103	     * expanded form.
104	     */
105	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
106	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
107	
108	    /**
109	     * Required national-number length per E.164 country code (the digits that follow the country
110	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
111	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
112	     */
113	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
114	        Map.of("1", 10, "61", 9);
115	
116	    /**
117	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
118	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
119	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
120	     * this table and accepts any 4-digit postcode.
121	     */
122	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
123	        "NSW", new int[] {2000, 2099},
124	        "VIC", new int[] {3000, 3099},
125	        "QLD", new int[] {4000, 4099});
126	
127	    /**
128	     * The maximum number of owners a single city may contain. A create request for a city that
129	     * already holds this many owners is rejected with a 409 response.
130	     */
131	    private static final int MAX_OWNERS_PER_CITY = 50;
132	
133	    /**
134	     * The maximum number of owners that may be registered in a single day. A create request made
135	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
136	     * response.
137	     */
138	    private static final int MAX_OWNERS_PER_DAY = 100;
139	
140	    /**
141	     * The number of owners that must already carry a day's {@code registrationDate} before a create
142	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
143	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
144	     */
145	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
146	
147	    /**
148	     * The tenure, in elapsed fiscal years, an owner must exceed to reach {@code membershipLevel} 4.
149	     * Tenure accrues from membership, so a newly created owner (zero tenure) never clears this
150	     * threshold and is therefore capped at level 3 on create.
151	     */
152	    private static final int TENURE_LEVEL_THRESHOLD_FISCAL_YEARS = 1;
153	
154	    /**
155	     * The HTTP header carrying a client-supplied idempotency token for owner creation. When a create
156	     * request repeats with a token already seen, the originally created owner is returned instead of
157	     * a second owner being created.
158	     */
159	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
