210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
213	        String idempotencyKey = idempotencyKey();
214	        if (idempotencyKey != null) {
215	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
216	            if (existingId != null) {
217	                Owner existing = this.clinicService.findOwnerById(existingId);
218	                if (existing != null) {
219	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
220	                }
221	            }
222	        }
223	        normalizeAddress(ownerFieldsDto);
224	        validateRequiredFields(ownerFieldsDto);
225	        normalizeTelephone(ownerFieldsDto);
226	        normalizeEmail(ownerFieldsDto);
227	        validatePostcode(ownerFieldsDto);
228	        String householdId = computeHouseholdId(ownerFieldsDto);
229	        rejectDuplicate(ownerFieldsDto, householdId);
230	        rejectCityAtCapacity(ownerFieldsDto);
231	        resolveRegistrationDate(ownerFieldsDto);
232	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
233	        HttpHeaders headers = new HttpHeaders();
234	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
235	        owner.setHouseholdId(householdId);
236	        assignCustomerCode(owner);
237	        assignMembershipNumber(owner);
238	        assignNamesakeCount(owner);
239	        assignBulkSignupWarning(owner);
240	        assignPossibleDuplicate(owner, ownerFieldsDto);
241	        assignHouseholdMembership(owner);
242	        assignMembership(owner);
243	        this.clinicService.saveOwner(owner);
244	        if (idempotencyKey != null) {
245	            this.idempotentCreates.put(idempotencyKey, owner.getId());
246	        }
247	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
248	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
249	            owner.getMembershipNumber());
250	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
251	        headers.setLocation(UriComponentsBuilder.newInstance()
252	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
253	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
254	    }
