377	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
378	        List<String> missingFields = new ArrayList<>();
379	        if (isBlank(ownerFieldsDto.getFirstName())) {
380	            missingFields.add("firstName");
381	        }
382	        if (isBlank(ownerFieldsDto.getLastName())) {
383	            missingFields.add("lastName");
384	        }
385	        if (isBlank(ownerFieldsDto.getAddress())) {
386	            missingFields.add("address");
387	        }
388	        if (isBlank(ownerFieldsDto.getCity())) {
389	            missingFields.add("city");
390	        }
391	        if (isBlank(ownerFieldsDto.getTelephone())) {
392	            missingFields.add("telephone");
393	        }
394	        if (!missingFields.isEmpty()) {
395	            throw new InvalidOwnerFieldsException(missingFields);
396	        }
397	    }
398	
399	    private static boolean isBlank(String value) {
400	        return value == null || value.trim().isEmpty();
401	    }
402	
403	    /**
404	     * Normalizes an owner's address on create, supporting both the structured form
405	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
406	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
407	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
408	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
409	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
410	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
411	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
412	     * flat {@code address} when no structured line is given - is written onto the request so it is what
413	     * gets validated, compared, stored and returned. Running before the required-field check means an
414	     * address that is blank in both forms after normalization is rejected like a missing one.
415	     */
416	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
417	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
418	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
419	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
420	        ownerFieldsDto.setAddressLine1(line1);
421	        ownerFieldsDto.setAddressLine2(line2);
422	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
423	    }
424	
425	    /**
426	     * Composes the effective address, preferring the structured form: when {@code line1} is present
427	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
428	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
429	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
430	     * left for the required-field check to reject) when no structured line is supplied.
431	     */
432	    private static String composeAddress(String line1, String line2, String flat) {
433	        if (line1 != null && !line1.isBlank()) {
434	            if (line2 != null && !line2.isBlank()) {
435	                return line1 + " " + line2;
436	            }
437	            return line1;
438	        }
439	        return flat;
440	    }
441	
442	    /**
443	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
444	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
445	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
446	     * address is returned unchanged, making it safe to apply to stored values during comparison.
447	     */
448	    private static String canonicalAddress(String address) {
449	        if (address == null) {
450	            return null;
451	        }
452	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
453	        if (collapsed.isEmpty()) {
454	            return "";
455	        }
456	        String[] tokens = collapsed.split(" ");
457	        StringBuilder sb = new StringBuilder(collapsed.length());
458	        for (int i = 0; i < tokens.length; i++) {
459	            if (i > 0) {
460	                sb.append(' ');
461	            }
462	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
463	        }
464	        return sb.toString();
465	    }
466	
467	    /**
468	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
469	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
470	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
471	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
472	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
473	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
474	     * written back onto the request so it is what gets stored and returned. Any value that cannot
475	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
476	     * {@code telephone}.
477	     */
478	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
479	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
480	    }
481	
482	    /**
483	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
484	     * (400) naming {@code telephone} when it cannot form a valid number.
485	     */
486	    private static String toE164(String telephone) {
487	        if (telephone == null) {
488	            throw new InvalidOwnerFieldsException(List.of("telephone"));
489	        }
490	        boolean hasCountryCode = telephone.trim().startsWith("+");
491	        String digits = telephone.replaceAll("\\D", "");
492	        String countryCode;
493	        String national;
494	        if (hasCountryCode) {
495	            countryCode = matchCountryCode(digits);
496	            national = digits;
497	        } else {
498	            countryCode = "61";
499	            if (digits.startsWith("0")) {
500	                digits = digits.substring(1);
501	            }
502	            national = "61" + digits;
503	        }
504	        if (!national.matches("[0-9]{8,15}")) {
505	            throw new InvalidOwnerFieldsException(List.of("telephone"));
506	        }
507	        if (countryCode != null) {
508	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
509	            if (requiredLength != null
510	                && national.length() - countryCode.length() != requiredLength) {
511	                throw new InvalidOwnerFieldsException(List.of("telephone"));
512	            }
513	        }
514	        return "+" + national;
515	    }
516	
517	    /**
518	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
519	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
520	     * the number is not length-checked against a country.
521	     */
522	    private static String matchCountryCode(String digits) {
523	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
524	            .filter(digits::startsWith)
525	            .max(Comparator.comparingInt(String::length))
526	            .orElse(null);
527	    }
528	
529	    /**
530	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
531	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}. Because the
532	     * key includes the computed {@code householdId} (a deterministic function of the normalized last
533	     * name and postcode, see {@link #computeHouseholdId}), an exact key match means the same person
534	     * re-registering in the same household; it also catches owners with no postcode (and therefore no
535	     * household) that share a telephone and email. A match is a 409.
536	     *
537	     * <p>Sharing a household is <em>not</em> on its own a duplicate: two distinct people in one
538	     * household (same last name and postcode, but different telephone/email) are legitimate household
539	     * members and are allowed through, so a household can accumulate several owner records.
540	     *
541	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
542	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
543	     * deleted.
544	     *
545	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
546	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail};
547	     * each existing owner's key is derived the same way before comparison. A match results in a 409
548	     * response naming {@code identityKey}.
549	     */
550	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
551	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
552	            return;
553	        }
554	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
555	        for (Owner existing : this.clinicService.findAllOwners()) {
556	            if (Boolean.TRUE.equals(existing.getDeleted())) {
557	                continue;
558	            }
559	            if (identityKey.equals(existingIdentityKey(existing))) {
560	                throw new DuplicateOwnerIdentityException(identityKey);
561	            }
562	        }
563	    }
564	
565	    /**
566	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
567	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
568	     * are expected to already be in their normalized (E.164, lower-cased) forms.
569	     */
570	    private static String identityKey(String telephone, String email, String householdId) {
571	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
572	    }
573	
574	    /**
575	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
576	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
577	     * the stored email is lower-cased, and the stored household id is used as-is.
578	     */
579	    private static String existingIdentityKey(Owner existing) {
580	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
581	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
582	        return identityKey(telephone, email, existing.getHouseholdId());
583	    }
584	
585	    private static String orEmpty(String value) {
586	        return value == null ? "" : value;
587	    }
588	
589	    /**
590	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
591	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
592	     */
593	    private static String normalizeExisting(String telephone) {
594	        try {
595	            return toE164(telephone);
596	        } catch (InvalidOwnerFieldsException ex) {
597	            return null;
598	        }
599	    }
600	
601	    /**
602	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
603	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
604	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
605	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
606	     */
607	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
608	        String city = ownerFieldsDto.getCity();
609	        int count = 0;
610	        for (Owner existing : this.clinicService.findAllOwners()) {
611	            if (city.equalsIgnoreCase(existing.getCity())) {
612	                count++;
613	            }
614	        }
615	        if (count >= MAX_OWNERS_PER_CITY) {
616	            throw new OwnerCityAtCapacityException(city);
617	        }
618	    }
619	
620	    /**
621	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
622	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
623	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
624	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
625	     */
626	    private void rejectDailyLimitReached(LocalDate registrationDate) {
627	        int count = 0;
628	        for (Owner existing : this.clinicService.findAllOwners()) {
629	            if (registrationDate.equals(existing.getRegistrationDate())) {
630	                count++;
631	            }
632	        }
633	        if (count >= MAX_OWNERS_PER_DAY) {
634	            throw new DailyOwnerLimitReachedException(registrationDate);
635	        }
636	    }
637	
638	    /**
639	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
640	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
641	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
642	     */
643	    private static String normalizeForComparison(String value) {
644	        if (value == null) {
645	            return "";
646	        }
647	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
648	    }
649	
650	    /**
651	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
652	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
653	     * written back onto the request so that is what gets stored and returned. A present but invalid
654	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
655	     */
656	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
657	        String email = ownerFieldsDto.getEmail();
658	        if (email == null) {
659	            return;
660	        }
661	        String trimmed = email.trim();
662	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
663	            throw new InvalidOwnerFieldsException(List.of("email"));
664	        }
665	        String normalized = trimmed.toLowerCase(Locale.ROOT);
666	        String domain = normalized.substring(normalized.indexOf('@') + 1);
667	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
668	            throw new InvalidOwnerFieldsException(List.of("email"));
669	        }
670	        ownerFieldsDto.setEmail(normalized);
671	    }
672	
673	    /**
674	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
675	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
676	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
677	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
678	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
679	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
680	     * as-is so it is stored and returned.
681	     */
682	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
683	        String postcode = ownerFieldsDto.getPostcode();
684	        if (postcode == null) {
685	            return;
686	        }
687	        if (!postcode.matches("[0-9]{4}")) {
688	            throw new InvalidOwnerFieldsException(List.of("postcode"));
689	        }
690	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
691	        if (range != null) {
692	            int value = Integer.parseInt(postcode);
693	            if (value < range[0] || value > range[1]) {
694	                throw new InvalidOwnerFieldsException(List.of("postcode"));
695	            }
696	        }
697	    }
698	
699	    /**
700	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
701	     * day. When the caller supplies no value it defaults to the server's current date; a value
702	     * provided in the request is kept. A supplied value later than the server's current date is
703	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
704	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
705	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
706	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
707	     * every value derived from the registration date is based on.
708	     */
709	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
710	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
711	        if (effective == null) {
712	            effective = LocalDate.now();
713	        }
714	        else if (effective.isAfter(LocalDate.now())) {
715	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
716	        }
717	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
718	    }
719	
720	    /**
721	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
722	     * forward, just like a weekend, until it reaches a non-holiday business day.
723	     */
724	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
725	        LocalDate.of(2026, 1, 1),
726	        LocalDate.of(2026, 1, 26),
727	        LocalDate.of(2026, 4, 25),
728	        LocalDate.of(2026, 12, 25),
729	        LocalDate.of(2026, 12, 28));
730	
731	    /**
732	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
733	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
734	     * is not a holiday is returned unchanged.
735	     */
736	    private static LocalDate toBusinessDay(LocalDate date) {
737	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
738	            date = date.plusDays(1);
739	        }
740	        return date;
741	    }
742	
743	    /**
744	     * Returns whether the given date falls on a Saturday or Sunday.
745	     */
746	    private static boolean isWeekend(LocalDate date) {
747	        return switch (date.getDayOfWeek()) {
748	            case SATURDAY, SUNDAY -> true;
749	            default -> false;
750	        };
751	    }
752	
753	    /**
754	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
755	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
756	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
757	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
758	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
759	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
760	     * pure function of region, telephone and last name.
761	     */
762	    private void assignCustomerCode(Owner owner) {
763	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
764	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
765	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
766	    }
767	
768	    /**
769	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
770	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
771	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
772	     * among them.
773	     */
774	    private String deduplicateCustomerCode(String customerCode) {
775	        Set<String> existing = new HashSet<>();
776	        for (Owner owner : this.clinicService.findAllOwners()) {
777	            if (owner.getCustomerCode() != null) {
778	                existing.add(owner.getCustomerCode());
779	            }
780	        }
781	        if (!existing.contains(customerCode)) {
782	            return customerCode;
783	        }
784	        int n = 2;
785	        while (existing.contains(customerCode + "-" + n)) {
786	            n++;
787	        }
788	        return customerCode + "-" + n;
789	    }
790	
791	    /**
792	     * Assigns the owner's {@code membershipNumber} on create, formatted
793	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the fiscal year of
794	     * the business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July, e.g. a
795	     * registration on 2026-08-03 falls in fiscal year 2027 and yields {@code 'NSW-1A2B3C4D-M27'}).
796	     * Assigned after {@link #assignCustomerCode} and once {@code registrationDate} has been
797	     * defaulted, so both inputs are present.
798	     */
799	    private void assignMembershipNumber(Owner owner) {
800	        String yy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
801	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
802	    }
803	
804	    /**
805	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
806	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
807	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
808	     */
809	    private void assignNamesakeCount(Owner owner) {
810	        String firstName = owner.getFirstName();
811	        String lastName = owner.getLastName();
812	        int count = 0;
813	        for (Owner existing : this.clinicService.findAllOwners()) {
814	            if (firstName.equalsIgnoreCase(existing.getFirstName())
815	                && lastName.equalsIgnoreCase(existing.getLastName())) {
816	                count++;
817	            }
818	        }
819	        owner.setNamesakeCount(count);
820	    }
821	
822	    /**
823	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
824	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
825	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
826	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
827	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
828	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
829	     * tenure, so the tenure bonus never applies on create.
830	     */
831	    private void assignMembership(Owner owner) {
832	        int points = 0;
833	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
834	            points += 2;
835	        }
836	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
837	            points += 1;
838	        }
839	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
840	            points += 2;
841	        }
842	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
843	            points += 3;
844	        }
845	        owner.setMembershipPoints(points);
846	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
847	    }
848	
849	    /**
850	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
851	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
852	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
853	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
854	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
855	     */
856	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
857	        String householdId = owner.getHouseholdId();
858	        if (householdId == null || householdId.isBlank()) {
859	            return derivedLevel;
860	        }
861	        Integer maxHouseholdLevel = null;
862	        for (Owner existing : this.clinicService.findAllOwners()) {
863	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
864	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
865	                maxHouseholdLevel = existing.getMembershipLevel();
866	            }
867	        }
868	        if (maxHouseholdLevel == null) {
869	            return derivedLevel;
870	        }
871	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
872	    }
873	
874	    /**
875	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
876	     * 4-5, and 4 for 6 or more points.
877	     */
878	    private int membershipLevelForPoints(int points) {
879	        if (points <= 1) {
880	            return 1;
881	        }
882	        if (points <= 3) {
883	            return 2;
884	        }
885	        if (points <= 5) {
886	            return 3;
887	        }
888	        return 4;
889	    }
890	
891	    /**
892	     * The tenure, in elapsed fiscal years, of a newly created owner. Tenure accrues from membership
893	     * over time, and a new owner has not been a member for any elapsed fiscal year yet, so this is
894	     * always {@code 0} on create (regardless of any backdated {@code registrationDate}).
895	     */
896	    private long tenureFiscalYears(Owner owner) {
897	        return 0L;
898	    }
899	
900	    /**
901	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
902	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
903	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
904	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
905	     * pre-existing owners for that day.
906	     */
907	    private void assignBulkSignupWarning(Owner owner) {
908	        LocalDate registrationDate = owner.getRegistrationDate();
909	        int count = 0;
910	        for (Owner existing : this.clinicService.findAllOwners()) {
911	            if (registrationDate.equals(existing.getRegistrationDate())) {
912	                count++;
913	            }
914	        }
915	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
916	    }
917	
918	    /**
919	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
920	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
921	     * possible duplicate when an existing owner shares its {@code lastName} (compared
922	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
923	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
924	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
925	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
926	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
927	     *
928	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
929	     * has deliberately opted into an existing household, so its shared last name and postcode are
930	     * expected rather than a suspected duplicate.
931	     */
932	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
933	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
934	            owner.setPossibleDuplicate(false);
935	            owner.setPossibleDuplicateOf(null);
936	            return;
937	        }
938	        String lastName = owner.getLastName();
939	        String postcode = owner.getPostcode();
940	        String telephone = owner.getTelephone();
941	        Integer matchId = null;
942	        if (postcode != null) {
943	            for (Owner existing : this.clinicService.findAllOwners()) {
944	                if (lastName.equalsIgnoreCase(existing.getLastName())
945	                    && postcode.equals(existing.getPostcode())
946	                    && !postcode.isBlank()
947	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
948	                    && existing.getId() != null
949	                    && (matchId == null || existing.getId() < matchId)) {
950	                    matchId = existing.getId();
951	                }
952	            }
953	        }
954	        owner.setPossibleDuplicate(matchId != null);
955	        owner.setPossibleDuplicateOf(matchId);
956	    }
957	
958	    /**
959	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
960	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
961	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
962	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
963	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
964	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
965	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
966	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
967	     * ({@link #assignHouseholdMembership}).
968	     */
969	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
970	        String postcode = ownerFieldsDto.getPostcode();
971	        if (postcode == null || postcode.isBlank()) {
972	            return null;
973	        }
974	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
975	        return shaHexUpper(lastName + "|" + postcode, 12);
976	    }
977	
978	    /**
979	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
980	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
981	     * every existing owner already carrying the same identifier. Runs after the owner's
982	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
983	     * Left {@code null} when the owner belongs to no household.
984	     */
985	    private void assignHouseholdMembership(Owner owner) {
986	        String householdId = owner.getHouseholdId();
987	        if (householdId == null || householdId.isBlank()) {
988	            owner.setHouseholdMemberCount(null);
989	            return;
990	        }
991	        int count = 1;
992	        for (Owner existing : this.clinicService.findAllOwners()) {
993	            if (householdId.equals(existing.getHouseholdId())) {
994	                count++;
995	            }
996	        }
997	        owner.setHouseholdMemberCount(count);
998	    }
999	
1000	    /**
1001	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1002	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
1003	     * identifier, both stable functions of their inputs.
1004	     */
1005	    private static String shaHexUpper(String input, int length) {
1006	        try {
1007	            byte[] digest = MessageDigest.getInstance("SHA-256")
1008	                .digest(input.getBytes(StandardCharsets.UTF_8));
1009	            StringBuilder hex = new StringBuilder(digest.length * 2);
1010	            for (byte b : digest) {
1011	                hex.append(String.format("%02x", b));
1012	            }
1013	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1014	        } catch (NoSuchAlgorithmException ex) {
1015	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1016	        }
1017	    }
1018	}
